(()=>{
const names={milk:'Milk',syrup:'Rooh Afza',sugar:'Sugar',ice:'Ice',tea:'Tea',sprite:'Sprite',lemon:'Lemon',salt:'Salt'};
const colors={milk:'#fffef6',syrup:'#eb454a',sugar:'#ffffff',ice:'#b9e6fa',tea:'#523024',sprite:'#e5e8e7',lemon:'#f5d65c',salt:'#ffffff'};
const drawings={milk:'<path d="M17 20 23 10h17l7 10v34H17Z M17 20h30 M23 10v10 M37 11l-4 9 M24 29h16v16H24Z"/><path d="m28 36 3-3 5 4-3 4Z" fill="currentColor"/>',syrup:'<path d="M27 8h11v10l5 9v29H22V27l5-9Z M27 13h11 M23 31h19 M23 45h19"/><path d="M27 35h10v7H27Z" fill="#eb454a"/><path d="m26 51 13-1"/>',sugar:'<path d="m15 29 13-7 13 7v15l-13 8-13-8Z M15 29l13 8 13-8 M28 37v15 M33 19l10-6 11 6v13l-9 5 M43 26l11-7 M43 26v9 M33 19l10 7"/>',ice:'<path d="m11 24 13-8 13 8v16l-13 8-13-8Z M11 24l13 8 13-8 M24 32v16 M34 38l11-7 12 7v14l-12 7-11-7Z M34 38l11 7 12-7 M45 45v14"/><path d="m16 28 3 2m22 11 4 1" stroke="#5baacb"/>',tea:'<path d="M14 28h33v12q-1 14-16 14T14 40Z M47 31h4q13 0 6 12l-10 2 M12 57h39 M22 22q-7-6 0-12 M34 22q-7-6 0-12 M44 20q-6-5 0-10"/><path d="M18 32h25" stroke="#523024" stroke-width="5"/>',sprite:'<path d="M27 8h11v10l6 12v25H21V30l6-12Z M27 13h11 M22 32h21 M22 46h21"/><path d="m26 38 11-3-8 8 10-3" stroke="#418969"/><circle cx="28" cy="25" r="1"/><circle cx="35" cy="29" r="1"/>',lemon:'<path d="M10 27 53 16q9 30-15 37T10 27Z" fill="#fff0a0"/><path d="m17 31 29-8q5 21-10 23T17 31Z M32 28l4 18 M32 28l-10 12 M32 28l14 7"/>',salt:'<path d="M24 22v-8q9-7 18 0v8l5 8v26H19V30Z M24 22h18 M24 18h18 M26 34h14v15H26"/><path d="M35 38h-5v4h5v4h-5"/>'};
const icons=Object.fromEntries(Object.entries(drawings).map(([k,v])=>[k,`<svg viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${v}</svg>`]));
const el=id=>document.getElementById(id);let chosen=null,round=null,clockId=null,launchId=null,quantity=1,drag=null,suppressClick=false;
el('ingredient-tools').innerHTML=Object.keys(names).map(k=>`<button class="ingredient-tool" data-ingredient="${k}" aria-label="Select ${names[k]}" aria-pressed="false">${icons[k]}<span>${names[k]}</span></button>`).join('');
function choose(k){if(!round?.active)return;chosen=k;el('play').classList.add('holding-ingredient');document.querySelectorAll('[data-ingredient]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ingredient===k)));el('held-icon').innerHTML=icons[k];el('held-icon').hidden=true;el('glass-help').textContent=`${names[k]} selected · click the glass to add ${quantity} pt`;el('glass-drop').setAttribute('aria-label',`Add ${quantity} pt ${names[k]} to the glass`);}
function clearCursor(){chosen=null;el('play').classList.remove('holding-ingredient');el('held-icon').hidden=true;document.querySelectorAll('[data-ingredient]').forEach(b=>b.setAttribute('aria-pressed','false'));}
function remaining(){return round?.deadline?Math.max(0,(round.deadline-performance.now())/1000):75;}
function tick(){if(!round?.active)return;const seconds=remaining();el('seconds').textContent=String(Math.ceil(seconds)).padStart(2,'0');el('timer-track').style.width=(seconds/75*100)+'%';el('receipt').classList.toggle('urgent',seconds<=15);if(seconds<=0)finish(false,'Time’s up! Try this order again.');}
function update(){const r=round;el('undo-step').disabled=!r.active||!r.history.length;document.querySelectorAll('[data-method]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.method===r.processed)));let total=0;el('liquid-layers').innerHTML=r.layers.map(layer=>{const h=layer.amount/24*268;const y=350-total/24*268-h;total+=layer.amount;return `<rect x="62" y="${y}" width="196" height="${h}" fill="${colors[layer.key]}" stroke="#7b746344" stroke-width=".7"/>`;}).join('');el('fill-total').textContent=total+' / 24 pt';el('added-list').textContent=Object.entries(r.amounts).filter(([,n])=>n).map(([k,n])=>`${names[k]} ${n} pt`).join(' · ')||'Your glass is empty';el('receipt-lines').innerHTML=Object.entries(r.recipe.amounts).map(([k,n])=>`<li class="${(r.amounts[k]||0)===n?'met':''}"><span>${names[k]}</span><b>${r.amounts[k]||0} / ${n} pt</b></li>`).join('');el('method-done').textContent=r.processed?`${r.processed===r.recipe.action?'✓':'✗'} ${r.processed}`:`Then ${r.recipe.action}`;}
function pour(){if(!round?.active||!chosen)return;if(remaining()<=0){tick();return;}const total=Object.values(round.amounts).reduce((a,b)=>a+b,0);if(total+quantity>24){el('game-message').textContent='The glass is full. Undo the last pour to make room.';return;}remember();round.amounts[chosen]=(round.amounts[chosen]||0)+quantity;round.layers.push({key:chosen,amount:quantity});round.processed=null;el('game-message').textContent=`Added ${quantity} pt ${names[chosen]}.`;el('glass-drop').classList.remove('pour-flash');void el('glass-drop').offsetWidth;el('glass-drop').classList.add('pour-flash');update();}
function finish(ok,message){if(!round?.active)return;round.active=false;Baristas.record(round.profile,ok);el('cup-note-panel').hidden=true;el('undo-step').disabled=true;if(el('scores-dialog').open)el('scores-dialog').close();clearInterval(clockId);clearTimeout(launchId);clearCursor();el('game-result').hidden=false;el('game-result').classList.toggle('won',ok);el('round-title').textContent=ok?'Shabaash!':'One more cup?';el('round-detail').textContent=message;el('game-message').textContent=message;el('serve-drink').disabled=true;el('glass-drop').disabled=true;document.querySelectorAll('.ingredient-tool,[data-method]').forEach(b=>b.disabled=true);el('retry-round').focus();}
function start(index){el('cloud-score-status').textContent='';clearInterval(clockId);clearTimeout(launchId);clearCursor();const recipe=CafeRules.recipes[index];round={index,recipe,amounts:{},layers:[],history:[],profile:Baristas.current().id,processed:null,active:true,deadline:null};el('cup-note-panel').hidden=true;el('cup-message').value='';el('cup-lettering').textContent='';el('cup-lettering').setAttribute('font-size','34');el('play').hidden=false;el('play').inert=false;el('order-name').textContent=recipe.name;el('order-prompt').textContent=recipe.prompt;el('game-result').hidden=true;el('receipt').classList.remove('urgent');el('seconds').textContent='75';el('timer-track').style.width='100%';el('serve-drink').disabled=false;el('glass-drop').disabled=false;document.querySelectorAll('.ingredient-tool,[data-method]').forEach(b=>b.disabled=false);el('game-message').textContent='Follow the points on the receipt. Finish with the right action, then serve!';el('glass-help').textContent='Pick an ingredient, then click the glass. Or drag it here.';el('glass-drop').setAttribute('aria-label','Empty glass — select an ingredient first');update();go('play');launchId=setTimeout(()=>{if(!round?.active)return;round.deadline=performance.now()+75000;clockId=setInterval(tick,100);tick();},1100);}
window.cafeRoundActive=()=>Boolean(round?.active);window.startCafeRound=index=>Baristas.require(()=>start(index));
el('ingredient-tools').addEventListener('click',e=>{const b=e.target.closest('[data-ingredient]');if(!b)return;if(suppressClick){suppressClick=false;return;}choose(b.dataset.ingredient);});
el('ingredient-tools').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-ingredient]');if(!b||!round?.active)return;drag={key:b.dataset.ingredient,x:e.clientX,y:e.clientY,moved:false};b.setPointerCapture(e.pointerId);});
window.addEventListener('pointermove',e=>{if(drag&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6){drag.moved=true;choose(drag.key);}const rect=el('glass-drop').getBoundingClientRect();const overGlass=e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom;el('held-icon').hidden=!(chosen&&round?.active&&(overGlass||drag?.moved));el('held-icon').style.transform=`translate(${e.clientX-19}px,${e.clientY-19}px)`;},{passive:true});
window.addEventListener('pointerup',e=>{if(drag?.moved){const rect=el('glass-drop').getBoundingClientRect();if(e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom)pour();suppressClick=true;setTimeout(()=>{suppressClick=false;},0);}drag=null;});window.addEventListener('pointercancel',()=>{drag=null;});
el('glass-drop').onclick=pour;
document.querySelectorAll('[data-quantity]').forEach(b=>b.onclick=()=>{quantity=Number(b.dataset.quantity);document.querySelectorAll('[data-quantity]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(chosen)choose(chosen);});
document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{if(!round?.active)return;if(remaining()<=0){tick();return;}const method=b.dataset.method;if(method!==round.recipe.action){remember();round.processed=method;el('game-message').textContent=`${method} isn’t right for this drink. Undo that step, then ${round.recipe.action}.`;update();return;}const check=CafeRules.judge(round.recipe,round.amounts,method,remaining());if(!check.ok){el('game-message').textContent=check.reason;return;}remember();round.processed=method;el('glass-drop').classList.remove('shake-cup','stir-cup','boil-cup');void el('glass-drop').offsetWidth;el('glass-drop').classList.add(method+'-cup');el('game-message').textContent='Perfect. Your drink is ready to serve!';update();});
function remember(){round.history.push({amounts:{...round.amounts},layers:round.layers.map(x=>({...x})),processed:round.processed});}
el('undo-step').onclick=()=>{if(!round?.active||!round.history.length)return;if(remaining()<=0){tick();return;}const old=round.history.pop();round.amounts=old.amounts;round.layers=old.layers;round.processed=old.processed;el('game-message').textContent='Last step undone. Your timer keeps running.';el('cup-note-panel').hidden=true;update();};
el('serve-drink').onclick=()=>{if(!round?.active)return;if(remaining()<=0){tick();return;}clearCursor();el('cup-note-panel').hidden=false;el('cup-message').focus();};
el('cup-message').oninput=()=>{const text=el('cup-message').value.trim();el('cup-lettering').textContent=text;el('cup-lettering').setAttribute('font-size',text?String(Math.min(22,95/Math.max(text.length,1))):'34');};
el('confirm-serve').onclick=()=>{if(!round?.active)return;const result=CafeRules.judge(round.recipe,round.amounts,round.processed,remaining());finish(result.ok,result.reason+(result.ok?` Served with ${Math.ceil(remaining())} seconds left.`:''));};
el('retry-round').onclick=()=>Baristas.require(()=>start(round.index));el('reset-cup').onclick=()=>Baristas.require(()=>start(round.index));el('another-order').onclick=()=>{clearInterval(clockId);clearTimeout(launchId);const previous=round?.index??-1;if(round)round.active=false;clearCursor();window.pickNextCafeDrink(previous);};
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{if(round?.active){round.active=false;clearInterval(clockId);clearTimeout(launchId);clearCursor();el('game-result').hidden=false;el('round-title').textContent='Cup set aside';el('round-detail').textContent='Restart this cup when you’re ready.';el('serve-drink').disabled=true;}}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')clearCursor();});
})();
